247	    /**
248	     * Builds an owner's customer code formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where CITY3 is the
249	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
250	     * last name and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number
251	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
252	     */
253	    private String generateCustomerCode(Owner owner) {
254	        String city = owner.getCity();
255	        int sequence = (int) ownerRepository.findAll().stream()
256	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
257	            .count() + 1;
258	        return String.format("%s-%s-%04d", prefix3(city), prefix3(owner.getLastName()), sequence);
259	    }
260	
261	    /** The upper-cased first three letters of {@code value} (fewer if it is shorter). */
262	    private static String prefix3(String value) {
263	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
264	    }
265	
266	    /**
267	     * Whether any existing owner has the given derived identity key. This is the single basis for
268	     * duplicate detection: a create is rejected only when the whole key matches an existing owner
269	     * exactly. See {@link Owner#getIdentityKey()} for the key's definition.
270	     */
271	    @Override
272	    @Transactional(readOnly = true)
273	    public boolean existsOwnerWithIdentityKey(String identityKey) throws DataAccessException {
274	        if (identityKey == null) {
275	            return false;
276	        }
277	        return ownerRepository.findAll().stream()
278	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
279	    }
280	
281	    /**
282	     * Counts the existing owners whose firstName and lastName match the given values
283	     * case-insensitively. Used to record an owner's namesake count at creation time.
284	     */
285	    @Override
286	    @Transactional(readOnly = true)
287	    public int countOwnersByName(String firstName, String lastName) throws DataAccessException {
288	        if (firstName == null || lastName == null) {
289	            return 0;
290	        }
291	        return (int) ownerRepository.findAll().stream()
292	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
293	                && lastName.equalsIgnoreCase(existing.getLastName()))
294	            .count();
295	    }
296	
297	    /**
298	     * Counts the existing owners whose city matches the given value case-insensitively.
299	     * Used to enforce the per-city capacity rule at creation time.
300	     */
301	    @Override
302	    @Transactional(readOnly = true)
303	    public int countOwnersByCity(String city) throws DataAccessException {
304	        if (city == null) {
305	            return 0;
306	        }
307	        return (int) ownerRepository.findAll().stream()
308	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
309	            .count();
310	    }
311	
312	    /**
313	     * Counts the existing owners whose registration date matches the given value.
314	     * Used to enforce the per-day owner creation limit.
315	     */
316	    @Override
317	    @Transactional(readOnly = true)
318	    public int countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
319	        if (registrationDate == null) {
320	            return 0;
321	        }
322	        return (int) ownerRepository.findAll().stream()
323	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
324	            .count();
325	    }
