327	    @Override
328	    @Transactional(readOnly = true)
329	    public boolean existsOwnerInHousehold(String lastName, String address) throws DataAccessException {
330	        return !findHouseholdMembers(lastName, address).isEmpty();
331	    }
332	
333	    /**
334	     * Returns the existing owners that belong to the household identified by the given last name
335	     * and address, comparing both fields in their normalized form. An empty list is returned when
336	     * either field is absent (no household can be formed).
337	     */
338	    private List<Owner> findHouseholdMembers(String lastName, String address) {
339	        String normalizedLastName = normalizeHouseholdField(lastName);
340	        String normalizedAddress = normalizeHouseholdAddress(address);
341	        if (normalizedLastName == null || normalizedAddress == null) {
342	            return List.of();
343	        }
344	        return ownerRepository.findAll().stream()
345	            .filter(existing -> normalizedLastName.equals(normalizeHouseholdField(existing.getLastName()))
346	                && normalizedAddress.equals(normalizeHouseholdAddress(existing.getAddress())))
347	            .toList();
348	    }
349	
350	    /**
351	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
352	     * runs of whitespace to a single space and lower-casing, so values that differ only in
353	     * whitespace or letter case are treated as equal.
354	     */
355	    private static String normalizeHouseholdField(String value) {
356	        if (value == null) {
357	            return null;
358	        }
359	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
360	    }
361	
362	    /**
363	     * Normalizes an address for household comparison and identity using the same canonical form
364	     * applied when an owner is created (trim/collapse whitespace, upper-case, expand common
365	     * abbreviations), so comparisons always use the normalized address regardless of the form in
366	     * which either value was originally supplied. Returns {@code null} when the address is absent
367	     * or blank, since no household can be formed without one.
368	     */
369	    private static String normalizeHouseholdAddress(String address) {
370	        String normalized = AddressNormalizer.normalize(address);
371	        if (normalized == null || normalized.isBlank()) {
372	            return null;
373	        }
374	        return normalized;
375	    }
376	
377	    /**
378	     * Places {@code owner} into the household formed by owners that share its (normalized) last
379	     * name and address, and returns the household's stable shared identifier. If any existing
380	     * member already carries a household id it is reused; otherwise a stable id is derived from
381	     * the shared last name and address. Every member missing an id (including the given owner)
382	     * is assigned the shared value so all owners in the household agree on it.
383	     */
384	    @Override
385	    @Transactional
386	    public String assignHousehold(Owner owner) throws DataAccessException {
387	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
388	        if (members.isEmpty()) {
389	            return null;
390	        }
391	        String householdId = members.stream()
392	            .map(Owner::getHouseholdId)
393	            .filter(id -> id != null && !id.isBlank())
394	            .findFirst()
395	            .orElseGet(() -> generateHouseholdId(owner.getLastName(), owner.getAddress()));
396	        for (Owner member : members) {
397	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
398	                member.setHouseholdId(householdId);
399	                ownerRepository.save(member);
400	            }
401	        }
402	        owner.setHouseholdId(householdId);
403	        return householdId;
404	    }
405	
406	    /**
407	     * Derives a stable household identifier from the normalized last name and address as the
408	     * first 16 upper-case hex characters of their SHA-256 digest, so the same household always
409	     * maps to the same value regardless of creation order.
410	     */
411	    private static String generateHouseholdId(String lastName, String address) {
412	        String seed = normalizeHouseholdField(lastName) + "\n" + normalizeHouseholdAddress(address);
413	        try {
414	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
415	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
416	            StringBuilder sb = new StringBuilder(hash.length * 2);
417	            for (byte b : hash) {
418	                sb.append(String.format("%02X", b));
419	            }
420	            return sb.substring(0, 16);
421	        }
422	        catch (NoSuchAlgorithmException e) {
423	            throw new IllegalStateException("SHA-256 not available", e);
424	        }
425	    }
426	
427	    @Override
428	    @Transactional(readOnly = true)
429	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
430	        return ownerRepository.findByLastName(lastName);
431	    }
432	
433	    @Override
434	    @Transactional(readOnly = true)
435	    public Collection<Visit> findVisitsByPetId(int petId) {
436	        return visitRepository.findByPetId(petId);
437	    }
438	
439	    @Override
440	    @Transactional(readOnly = true)
441	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
442	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
443	    }
444	
445	    private <T> T findEntityById(Supplier<T> supplier) {
446	        try {
447	            return supplier.get();
448	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
449	            // Just ignore not found exceptions for Jdbc/Jpa realization
450	            return null;
451	        }
452	    }
453	
454	}
