30	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "formatContactPreference")
31	    @Mapping(target = "bulkSignupWarning", ignore = true)
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /** Fixed city-to-region table used to derive an owner's {@code locality}. */
35	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
36	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
37	
38	    /** Region to inclusive 4-digit postcode range {low, high}, used to derive an
39	     *  owner's {@code locality} from its postcode ahead of the city table. */
40	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
41	        "NSW", new int[] {2000, 2099},
42	        "VIC", new int[] {3000, 3099},
43	        "QLD", new int[] {4000, 4099});
44	
45	    /**
46	     * Derives an owner's preferred contact channel for the read-only {@code contactPreference}
47	     * field: {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
48	     */
49	    @Named("formatContactPreference")
50	    default String formatContactPreference(Owner owner) {
51	        if (owner == null) {
52	            return null;
53	        }
54	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
55	        return hasEmail ? "EMAIL" : "PHONE";
56	    }
57	
58	    /**
59	     * Derives an owner's {@code locality} by preferring the postcode: the region whose
60	     * inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the
61	     * postcode is used first. When the postcode is absent or in no known range, it falls
62	     * back to the fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
63	     * Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the city is not in the table.
64	     */
65	    @Named("formatLocality")
66	    default String formatLocality(Owner owner) {
67	        if (owner == null) {
68	            return null;
69	        }
70	        String postcode = owner.getPostcode();
71	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
72	            int value = Integer.parseInt(postcode);
73	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
74	                int[] range = entry.getValue();
75	                if (value >= range[0] && value <= range[1]) {
76	                    return entry.getKey();
77	                }
78	            }
79	        }
80	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
81	    }
82	
83	    /**
84	     * Determines an owner's numeric membership level for the read-only {@code membershipLevel}
85	     * field, assigned at creation and ranging from 1 to 3: it starts at 1, gains 1 when an email
86	     * address is present, gains 1 when the owner had no namesakes at creation (namesakeCount is 0),
87	     * and is capped at 3. Level 4 is reserved for tenure.
88	     */
89	    @Named("formatMembershipLevel")
90	    default Integer formatMembershipLevel(Owner owner) {
91	        if (owner == null) {
92	            return null;
93	        }
94	        int level = 1;
95	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
96	        if (hasEmail) {
97	            level++;
98	        }
99	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
100	        if (noNamesakes) {
101	            level++;
102	        }
103	        return Math.min(level, 3);
104	    }
105	
106	    /**
107	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last
108	     * two digits of the registrationDate year (e.g. {@code 'SYD-SMI-0007-M26'}), for the read-only
109	     * {@code membershipNumber} field. Null when the customer code or registration date is absent.
110	     */
111	    @Named("formatMembershipNumber")
112	    default String formatMembershipNumber(Owner owner) {
113	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
114	            return null;
115	        }
116	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
117	    }
118	
119	    /**
120	     * Computes the Luhn check digit (0-9) over the digits contained in the owner's
121	     * {@code customerCode} for the read-only {@code checkDigit} field. Null when the
122	     * customer code is absent.
123	     */
124	    @Named("formatCheckDigit")
125	    default Integer formatCheckDigit(Owner owner) {
126	        if (owner == null || owner.getCustomerCode() == null) {
127	            return null;
128	        }
129	        String code = owner.getCustomerCode();
130	        int sum = 0;
131	        boolean dbl = true;
132	        for (int i = code.length() - 1; i >= 0; i--) {
133	            char c = code.charAt(i);
134	            if (c < '0' || c > '9') {
135	                continue;
136	            }
137	            int d = c - '0';
138	            if (dbl) {
139	                d *= 2;
140	                if (d > 9) {
141	                    d -= 9;
142	                }
143	            }
144	            sum += d;
145	            dbl = !dbl;
146	        }
147	        return (10 - (sum % 10)) % 10;
148	    }
149	
150	    /**
151	     * Formats an owner's stored names as {@code 'LastName, FirstName'} for the read-only
152	     * {@code displayName} field.
153	     */
154	    @Named("formatDisplayName")
