114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        LocalDate registrationDate = owner.resolveRegistrationDate();
120	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
121	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
122	        }
123	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
124	            return new ResponseEntity<>(HttpStatus.CONFLICT);
125	        }
126	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
127	        boolean householdExists = this.clinicService.existsOwnerInHousehold(owner.getLastName(), owner.getAddress());
128	        if (sharesHousehold && householdExists) {
129	            this.clinicService.assignHousehold(owner);
130	        }
131	        // All duplicate detection is consolidated into the owner's derived identity key (see
132	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
133	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
134	            return new ResponseEntity<>(HttpStatus.CONFLICT);
135	        }
136	        owner.setNamesakeCount(
137	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
138	        this.clinicService.saveOwner(owner);
139	        auditLogger.info("owner created: id={} customerCode={} registrationDate={}",
140	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
141	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
142	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
